+var researchTools = new ResearchTools();
+
+var tools = new List<AITool>
+{
+    AIFunctionFactory.Create(researchTools.SearchWeb),
+    AIFunctionFactory.Create(researchTools.AddNote),
+    AIFunctionFactory.Create(researchTools.GetNotes),
+};
+
+// ── Agent ──────────────────────────────────────────────────────────────
+var agent = chatClient.AsAIAgent(
+    instructions: """
+        You are a research agent. When the user gives you a topic:
+        1. Use SearchWeb to find relevant information (perform at least 2 searches
+           with different queries to get broad coverage).
+        2. Use AddNote to save each key finding as a short note.
+        3. Use GetNotes to review everything you have collected.
+        4. Produce a concise summary with the most important findings, citing
+           the sources you discovered.
+        Keep your final summary under 400 words.
+        """,
+    name: "ResearchAgent",
+    description: "Researches a topic by searching the web and taking notes.",
+    tools: tools,
+    loggerFactory: loggerFactory);
+
+// ── Run ────────────────────────────────────────────────────────────────
+var topic = args.Length > 0
+    ? string.Join(' ', args)
+    : "recent advances in quantum computing 2025";
+
+Console.WriteLine($"🔍 Researching: {topic}\n");
+
+await foreach (var update in agent.RunStreamingAsync($"Research the following topic: {topic}"))
+{
+    Console.Write(update.Text);
+}
+
+Console.WriteLine();
+
+// ── Tool implementations ───────────────────────────────────────────────
+public sealed class ResearchTools
+{
+    private readonly List<string> _notes = [];
+    private readonly HttpClient _http = new();
+
+    [Description("Searches the web for the given query and returns a summary of results. Use this to gather information about a topic.")]
+    public async Task<string> SearchWeb(
+        [Description("The search query string")] string query,
+        CancellationToken cancellationToken = default)
+    {
+        Console.WriteLine($"  🌐 Searching: \"{query}\"");
+
+        try
+        {
+            // Use Wikipedia API as a publicly-available, no-auth search endpoint
+            var encoded = Uri.EscapeDataString(query);
+            var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&srlimit=4&format=json&utf8=1";
+
+            var json = await _http.GetStringAsync(url, cancellationToken);
+
+            // Parse and extract snippets from the search results
+            using var doc = System.Text.Json.JsonDocument.Parse(json);
+            var results = doc.RootElement
+                .GetProperty("query")
+                .GetProperty("search");
+
+            if (results.GetArrayLength() == 0)
+            {
+                return $"No results found for \"{query}\".";
+            }
+
+            var sb = new System.Text.StringBuilder();
+            sb.AppendLine($"Search results for \"{query}\":");
+
+            foreach (var item in results.EnumerateArray())
+            {
+                var title = item.GetProperty("title").GetString();
+                var snippet = item.GetProperty("snippet").GetString();
+                // Strip HTML tags from the Wikipedia snippet
+                snippet = System.Text.RegularExpressions.Regex.Replace(snippet ?? "", "<.*?>", "");
+                sb.AppendLine($"- **{title}**: {snippet}");
+                sb.AppendLine($"  Source: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(title ?? "")}");
+            }
+
+            return sb.ToString();
+        }
+        catch (Exception ex)
+        {
+            return $"Search failed for \"{query}\": {ex.Message}";
+        }
+    }
+
+    [Description("Saves a research note. Use this to record key findings during research.")]
+    public string AddNote(
+        [Description("The note text to save")] string note)
+    {
+        _notes.Add(note);
+        Console.WriteLine($"  📝 Note #{_notes.Count} saved");
+        return $"Note #{_notes.Count} saved successfully.";
+    }
+
+    [Description("Returns all saved research notes so far.")]
+    public string GetNotes()
+    {
+        if (_notes.Count == 0)
+        {
+            return "No notes saved yet.";
+        }
+
+        var sb = new System.Text.StringBuilder();
+        sb.AppendLine($"All notes ({_notes.Count} total):");
+        for (var i = 0; i < _notes.Count; i++)
+        {
+            sb.AppendLine($"  {i + 1}. {_notes[i]}");
+        }
+
+        return sb.ToString();
+    }
+}

